import {readLanguageHandoff,switchLanguage} from '../language.mjs';
import {evaluate,PRESETS,base,countries,EU,isEU,SOURCES,VERSION,REVIEW_DATE,caseLabel,label,destinationOf,resolveVat} from './engine.mjs';
import {definitions,stepNames,groups,activeKeys} from './form.mjs';
import {testCases,runCase} from './cases.mjs';
let state={...base},step=0,resultTab='overview',activePreset='export',currentView='case';
const handoff=readLanguageHandoff();
if(handoff){
 for(const key of Object.keys(base)){
  const value=handoff.state?.[key];
  if(value==='UNKNOWN'||definitions[key]?.options.some(option=>option.value===value))state[key]=value;
 }
 step=Number.isInteger(handoff.step)&&handoff.step>=0&&handoff.step<=4?handoff.step:0;
 resultTab=['overview','invoice','sources'].includes(handoff.resultTab)?handoff.resultTab:'overview';
 activePreset=PRESETS.some(p=>p.id===handoff.activePreset)?handoff.activePreset:null;
 currentView=['case','rules','validation'].includes(handoff.currentView)?handoff.currentView:'case';
}
const $=q=>document.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list=(items,cls='pending-list')=>`<ul class="${cls}">${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
const refLinks=refs=>`<div class="ref-links">${[...new Set(refs)].filter(k=>SOURCES[k]).map(k=>`<a class="ref-chip" href="${SOURCES[k].url}" target="_blank" rel="noopener noreferrer">${esc(SOURCES[k].label)} ↗</a>`).join('')}</div>`;
function renderField(key,index){const d=definitions[key];return `<fieldset class="field"><legend><span class="field-num">${String(index+1).padStart(2,'0')}</span>${esc(d.label)}</legend>${d.select?`<select aria-label="${esc(d.label)}" data-key="${key}">${d.options.map(x=>`<option value="${x.value}" ${state[key]===x.value?'selected':''}>${esc(x.label)}</option>`).join('')}</select>`:`<div class="choice-grid ${d.single?'single':''}" role="group" aria-label="${esc(d.label)}">${d.options.map(x=>`<button type="button" class="choice ${state[key]===x.value?'selected':''}" data-key="${key}" data-value="${x.value}" aria-pressed="${state[key]===x.value}">${esc(x.label)}</button>`).join('')}</div>`}${d.help?`<p class="field-help">${esc(d.help)}</p>`:''}</fieldset>`;}
function renderQuestions(){
 $('#steps').innerHTML=stepNames.map((n,i)=>`<button class="step ${step===i?'active':''}" data-step="${i}" role="tab" aria-selected="${step===i}"><b>0${i+1}</b>${n}</button>`).join('');
 const intros=["Beteiligte und Abnehmerstatus wählen. Ansässigkeit, Lieferland und Nummernstaat getrennt prüfen.","Zuerst Vertragsart bestimmen. Werkmodul für Einkaufs- oder Verkaufsseite einzeln nutzen.","Tatsächlicher Transport, Tätigkeit und Fertigstellung entscheiden über den Leistungsort; die Rechnungsanschrift allein genügt nicht.","Staat der tatsächlich verwendeten Nummer dieses Umsatzes angeben. Die Nummer allein ändert den Leistungsort nicht.","Steuerbefreiung, OSS und Vereinfachungsregelung für Dreiecksgeschäfte haben eigene Bedingungen. Offene Punkte bleiben im Ergebnis sichtbar."];
 $('#question-body').innerHTML=`<p class="step-intro">${intros[step]}</p>`+groups(state)[step].map(renderField).join('')+(step===4?`<div class="mini-info"><strong>Aktueller Sachverhalt</strong><br>${esc(caseLabel(state))}<br>Tatsächliche Fakten auswählen. Belege, Nummern und Meldestand werden vom Nutzer bestätigt.</div>`:'');
 $('#step-count').textContent=`Schritt 0${step+1} / 05`;$('#back').disabled=step===0;$('#next').innerHTML=step===4?"Rechnungshinweise ansehen <span>↗</span>":"Weiter <span>→</span>";
 $('#presets').innerHTML=PRESETS.map(p=>`<button class="preset ${activePreset===p.id?'active':''}" data-preset="${p.id}"><strong>${esc(p.name)}</strong><small>${esc(p.hint)}</small></button>`).join('');
}
function checksPanel(r){if(!r.checks.length)return '';return `<section class="detail-section"><h3 class="detail-title"><span>Dreiecksgeschäft: Bedingungen</span><span class="count">${esc(({ELIGIBLE:"Laut Angaben erfüllt",POTENTIAL:"Möglicherweise anwendbar",NO:"Nicht anwendbar"})[r.triangleState]||"Noch zu prüfen")}</span></h3><div class="check-list">${r.checks.map(x=>`<div class="check-row"><span class="check-state ${x.status.toLowerCase()}">${x.status==='YES'?'✓':x.status==='NO'?'×':'?'}</span><span>${esc(x.label)}</span></div>`).join('')}</div>${refLinks(['triangle','triangleInvoice','zm'])}</section>`;}
function renderResult(){const r=evaluate(state),d=destinationOf(state),work=state.transaction==='WORK';
 $('#result-title').textContent=r.title;$('#result-summary').textContent=r.summary;$('#result-status').innerHTML=`<span class="status ${r.tone==='amber'?'amber':''}">${esc(r.status)}</span>`;
 $('#route-label').textContent=`${activePreset?"Beispiel":"Aktuelle Auswahl"} / ${work?(state.workLens==='IN'?"Werkvertrag im Einkauf":"Werkvertrag im Verkauf"):caseLabel(state)}`;
 $('#chain-result').textContent=r.chain;$('#moving-result').textContent=r.moving;$('#class-result').textContent=r.classification;$('#special-result').textContent=r.special;
 const branch=state.recipient==='BRANCH';
 $('#flow').innerHTML=`<div class="flow-label">${work?"Bewerteter Vertrag und Beteiligte":"Warenbewegung und Vertragskette"}<span>${work?(state.workLens==='IN'?"Einkaufsseite prüfen":"Verkaufsseite prüfen"):"Tatsächliche Lieferung prüfen"}</span></div><div class="flow-row"><div class="flow-node"><strong>Lieferant</strong><small>${esc(label(state.supplierCountry))}</small></div><span class="flow-arrow"></span><div class="flow-node emphasis"><strong>Deutsche GmbH</strong><small>${work?"Vor- und nachgelagerte Verträge einzeln prüfen":"Zwischenhändler dieses Umsatzes"}</small></div><span class="flow-arrow"></span><div class="flow-node"><strong>${branch?"EU-Niederlassung":state.buyer==='B2C'?"Privater Endverbraucher":"Endkunde"}</strong><small>${esc(label(d))}${branch?" · derselbe Rechtsträger":''}</small></div></div><div class="flow-foot">${work?"Werkvertrag: "+esc(r.classification)+" · Vertragsstufen getrennt prüfen":"Waren: "+esc(label(state.origin))+' → '+esc(label(d))+' · '+(branch?"Interne Verrechnung nach Einkauf":esc(state.buyer)+" Tatsächlicher Einkauf und Weiterverkauf")}</div>`;
 document.querySelectorAll('[data-result]').forEach(el=>{el.classList.toggle('active',el.dataset.result===resultTab);el.setAttribute('aria-selected',el.dataset.result===resultTab);});
 let html='';
 if(resultTab==='overview'){
  if(r.known.length)html+=`<section class="detail-section"><h3 class="detail-title"><span><b class="icon">✓</b>Nach aktuellen Angaben feststellbar</span><span class="count">${r.known.length} ${r.known.length===1?"Punkt":"Punkte"}</span></h3>${r.known.map(x=>`<div class="point"><strong>${esc(x.title)}</strong><p>${esc(x.text)}</p>${refLinks(x.refs)}</div>`).join('')}</section>`;
  html+=checksPanel(r);
  html+=`<section class="detail-section pending-section"><h3 class="detail-title"><span><b class="icon warn">!</b>Noch zu prüfen / zu erfüllende Bedingungen</span><span class="count">${r.pending.length} ${r.pending.length===1?"Punkt":"Punkte"}</span></h3>${r.pending.length?list(r.pending):"<p class=\"source-intro\">Nach den Angaben keine weiteren fehlenden Fakten erkannt. Tatsächliche Nachweise und anwendbare Regeln bleiben maßgeblich.</p>"}</section>`;
  if(r.actions.length)html+=`<section class="detail-section"><h3 class="detail-title">Nächste Schritte</h3>${list(r.actions,'action-list')}</section>`;
 }else if(resultTab==='invoice'){
  html=`<section class="detail-section"><h3 class="detail-title">01 · Lieferant → GmbH: Eingangsrechnung prüfen</h3>${r.incoming.length?list(r.incoming,'action-list'):"<p class=\"source-intro\">Zuerst wesentliche Fakten ergänzen; danach Behandlung der Eingangsrechnung festlegen.</p>"}</section><section class="detail-section"><h3 class="detail-title">02 · GmbH → Kunde: Ausgangsrechnung</h3>${r.outgoing.length?list(r.outgoing,'action-list'):"<p class=\"source-intro\">Ausgangsrechnung derzeit nicht abschließend festgelegt.</p>"}</section>`;
  if(r.wording)html+=`<section class="detail-section"><h3 class="detail-title">${work&&state.workLens==='IN'?"Rechnungstext des bewerteten Einkaufsvertrags":"Mustertext für den anwendbaren Fall"}</h3><div class="wording">${esc(r.wording)}</div><p class="wording-note">${esc(r.wordingNote)}</p><button class="btn secondary" id="copy-wording">Mustertext kopieren ↗</button></section>`;
  if(!r.wording&&!r.code.startsWith('ASK_'))html+=`<p class="wording-note">${esc(r.wordingNote)}</p>`;
  html+=`<div class="mini-info">Verwendete Nummern: Einkauf ${esc(label(resolveVat(state,state.purchaseVat)))} · Verkauf ${esc(label(resolveVat(state,state.salesVat)))}. Nummernstaat und Leistungsort getrennt prüfen. Vereinfachungsregelung für Dreiecksgeschäfte erfordert beidseitig dieselbe qualifizierte USt-IdNr.</div>`;
 }else html=`<section class="detail-section"><p class="source-intro">Amtliche Grundlagen für diesen Fall. Deutsches Recht ersetzt kein ausländisches Recht. Fassungen von Rechtsprechung und Verwaltungsanweisungen sind gesondert erläutert.</p>${r.refs.filter(k=>SOURCES[k]).map((k,i)=>{const x=SOURCES[k];return `<div class="source-row"><span class="source-no">${String(i+1).padStart(2,'0')}</span><div><a href="${x.url}" target="_blank" rel="noopener noreferrer">${esc(x.label)} ↗</a><p>${esc(x.detail)}</p></div></div>`;}).join('')}</section>`;
 $('#result-content').innerHTML=html;
}
function render(){renderQuestions();renderResult();}
function setField(k,v){state[k]=v;activePreset=null;if(k==='recipient'){state.invoice=v==='BRANCH'?'BRANCH':'CHAIN';if(v!=='BRANCH'&&state.buyer==='INTERNAL')state.buyer='B2B';}render();}
function showView(v){currentView=v;for(const id of ['case','rules','validation'])$(`#${id}-view`).hidden=id!==v;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===v));$('#breadcrumb').textContent={case:"Transaktion prüfen",rules:"Regeln & Grenzen",validation:"Prüfprotokoll"}[v];if(v==='validation')renderValidation();window.scrollTo({top:0,behavior:'auto'});}
function report(){const r=evaluate(state);return [`VAT NAVIGATOR | Grenzüberschreitende Umsatzsteuer der deutschen GmbH`,`Regelversion ${VERSION} · Rechtsstand geprüft ${REVIEW_DATE}`,`Erstellt am ${new Date().toLocaleString('de-DE',{timeZone:'Europe/Berlin'})} (Berliner Zeit)`,'',...activeKeys(state).map(k=>`${definitions[k].label} ${definitions[k].options.find(x=>x.value===state[k])?.label||state[k]}`),'',`Ergebnis:${r.title}`,r.summary,`Vertragsart:${r.classification}`,`Reihengeschäft：${r.chain}`,`Transportzuordnung:${r.moving}`,`Sonderregel:${r.special}`,'',"Nach aktuellen Angaben feststellbar:",...r.known.map(x=>`• ${x.title}：${x.text}`),'',"Dreiecksbedingungen:",...r.checks.map(x=>`• [${x.status}] ${x.label}`),'',"Noch zu prüfen:",...r.pending.map(x=>`• ${x}`),'',"Eingangsrechnung prüfen:",...r.incoming.map(x=>`• ${x}`),'',"Ausgangsrechnung:",...r.outgoing.map(x=>`• ${x}`),'',r.wording,r.wordingNote,'',"Amtliche Grundlagen:",...r.refs.filter(k=>SOURCES[k]).map(k=>`${SOURCES[k].label}\n${SOURCES[k].url}`),'',"Fakten, Nummern und Nachweise bestätigt der Nutzer. Ausländische Umsetzung gesondert prüfen. Keine Steuerbetragsberechnung und keine laufende Rechtsaktualisierung."].join('\n');}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast("Kopieren angefordert; alternativ Protokoll öffnen und manuell kopieren oder speichern");}catch{$('#record-text').value=text;$('#record-dialog').showModal();$('#record-text').select();toast("Bitte Protokoll manuell kopieren oder als Text speichern");}}
function showRecord(){$('#record-text').value=report();$('#record-dialog').showModal();}
function downloadRecord(){const blob=new Blob([report()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download="VAT-Navigator-Pruefprotokoll.txt";a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function renderRules(){const rules=[
 ["01 / Lieferkette","Zuerst Transportzuordnung, dann Sonderregeln","In der gewöhnlichen Warenkette ist nur eine Lieferung bewegt. Erster Lieferant transportiert: Eingangslieferung. Kunde transportiert: Weiterverkauf. Transportiert die GmbH, vorher verwendete Nummer des Abgangsstaats prüfen. Tatsächlicher Transporteur ist nicht zwingend vertraglich verantwortlich.",['chain','place']],
 ["02 / USt-IdNrn.","Unternehmenssitz, Staat der USt-IdNr. und Warenbewegung trennen","Die im Ein- und Ausgangsumsatz verwendeten USt-IdNrn. der GmbH sowie die USt-IdNrn. des Lieferanten und des Abnehmers erfassen. Sie beeinflussen die Transportzuordnung und Befreiungsvoraussetzungen, bestimmen den Leistungsort jedoch nicht allein. Eine ausländische USt-IdNr. begründet für sich keine feste Niederlassung.",['acquisition','fixed']],
 ["03 / Dreiecksgeschäft","Drei Beteiligte und qualifizierte Nummern aus drei Staaten","Bewegte Eingangslieferung; dieselbe GmbH-Nummer eines dritten Mitgliedstaats auf beiden Stufen; Kunde mit Bestimmungsstaatsnummer; GmbH dort nicht ansässig. Rechnung und korrekte ZM sind Umsetzungsbedingungen. Eine deutsche GmbH wird bei Ankunft in Deutschland durch Nummernwechsel nicht zum dort nicht ansässigen Erwerber.",['triangle','triangleInvoice','zm','luxury','buehler']],
 ['04 / B2C',"Verbraucherverkauf bedeutet nicht automatisch OSS","Nur bei bewegtem grenzüberschreitendem Verkauf der GmbH und unmittelbarer/mittelbarer Transportbeteiligung Fernverkauf weiter prüfen. Bei bewegtem Einkauf folgt regelmäßig ein ruhender Verkauf am Ziel. Gewöhnliche lokale Warenverkäufe sind nicht direkt OSS-fähig.",['distance','indirect','oss']],
 ['05 / €10,000',"Die Grenze ist eine begrenzte Ausnahme, kein Freibetrag","GmbH ausschließlich in Deutschland ansässig, Abgang Deutschland, relevante Fernverkäufe und TBE-Leistungen im Vorjahr und laufenden Jahr jeweils zusammen höchstens 10.000 EUR, kein Verzicht. Bei ausländischem Abgang greift diese deutsche Ausnahme nicht.",['distance','oss']],
 ["06 / Werkverträge","Einordnen, dann Fertigstellung und Leistungsort prüfen","Fremder Gegenstand und eigene Hauptstoffe können Werklieferung sein; nur Zutaten oder reine Arbeit regelmäßig Werkleistung. Herstellung aus eigenen Stoffen ist nicht automatisch Werklieferung. Fertigstellung vor Versand und wesentliche Montage am Ziel unterscheiden.",['work','workAdmin','install']],
 ["07 / Umsatzsteuer auf Werkverträge","Einkaufs- und Verkaufsvertrag getrennt prüfen","Echte ausländische Werklieferung und gewöhnliche Montage eigener Maschinen können unter § 13b verschieden behandelt werden. Reverse Charge im Einkauf überträgt sich nicht auf den Verkauf. Bei Bauleistungen Empfängerqualifikation zusätzlich prüfen.",['reverse','invoiceSpecial']],
 ["08 / Leistungsort","B2B-Empfänger, B2C-Tätigkeit, Grundstückslage","B2B-Werkleistungen an beweglichen Sachen regelmäßig am tatsächlichen Empfängerunternehmen oder an der empfangenden Betriebsstätte; B2C am Tätigkeitsort (§ 3a Abs. 3 Nr. 3a Buchst. b). Grundstücke und Drittlandsnutzung gesondert prüfen.",['service']],
 ["09 / Begriffe", "Eine Warenbewegung, zwei Lieferungen", "Beim Reihengeschäft wird derselbe Gegenstand nacheinander geliefert, gelangt aber unmittelbar vom ersten Lieferer zum letzten Abnehmer. Nur einer Lieferung wird die Warenbewegung zugeordnet (bewegte Lieferung); die andere ist eine ruhende Lieferung.", ["chain", "place"]],
 ["10 / Begriffe", "Steuerfrei, nicht steuerbar und Reverse Charge", "Steuerfrei: Der Umsatz ist im Inland steuerbar, erfüllt aber einen Befreiungstatbestand. Nicht im Inland steuerbar: Der Leistungsort liegt im Ausland. Steuerschuldnerschaft des Leistungsempfängers: Der Empfänger schuldet die Steuer; der Umsatz ist dadurch nicht steuerfrei.", ["place", "export", "reverse"]],
 ["11 / Begriffe", "Innergemeinschaftlicher Erwerb und Vorsteuerabzug", "Der innergemeinschaftliche Erwerb erfasst insbesondere den unternehmerischen Warenbezug aus einem anderen Mitgliedstaat. Der Vorsteuerabzug setzt die gesetzlichen Voraussetzungen voraus. Ausländische Umsatzsteuer und die zusätzliche Erwerbsteuer im Staat der verwendeten USt-IdNr. berechtigen nicht automatisch zum deutschen Vorsteuerabzug.", ["acquisition", "input"]],
 ];
 $('#rules-view').innerHTML=`<div class="section-heading"><div class="eyebrow">REGELN & GRENZEN · V2</div><h1>Mehr Fälle, klar definierte Grenzen.</h1><p>Vier Empfängerkategorien, B2B/B2C, Vereinfachungsregelung für Dreiecksgeschäfte und Werkverträge folgen derselben sachverhaltsbezogenen Prüfreihenfolge.</p></div><div class="rules-grid">${rules.map(([no,title,text,refs])=>`<article class="rule-card"><span class="rule-no">${no}</span><h3>${title}</h3><p>${text}</p>${refLinks(refs)}</article>`).join('')}<article class="rule-card wide-card"><h3>Abdeckung und gesondert zu prüfende Themen</h3><table class="rule-table"><thead><tr><th>Bereich</th><th>Das Tool bietet</th><th>Gesondert zu prüfen</th></tr></thead><tbody><tr><td>Deutsche / andere EU-Lieferanten</td><td>Abgang EU27, Lieferung nach DE/EU/Drittland</td><td>Einfuhr mit Drittlandsabgang, Nordirland und Sondergebiete</td></tr><tr><td>Regelbesteuerte Waren</td><td>Niederlassungen, B2B/B2C, Zuordnung, Nummern und Dreiecksprüfung</td><td>Besondere §-13b-Waren, Neufahrzeuge, Verbrauchsteuern, Organschaft, Differenz-/Kleinunternehmerbesteuerung, Plattformfiktionen usw.</td></tr><tr><td>Bearbeitung / Reparatur / Montage</td><td>Einordnung und Leistungsort des gewählten Einkaufs- oder Verkaufsvertrags</td><td>Komplexe einheitliche/mehrere Leistungen, konkrete Verträge und Stoffgehalt, ausländisches Recht</td></tr><tr><td>Steuerbefreiung und Meldungen</td><td>Bedingungen, Rechnungstexte, Eingangsrechnungscheck und Rechtsgrundlagen</td><td>Belege und Nummerngültigkeit bestätigt der Nutzer; keine Betragsberechnung oder Echtzeitprüfung</td></tr></tbody></table><p>Rechtsgrundlagen geprüft am ${REVIEW_DATE}. Verwaltungslinks nennen ihre Ausgangsfassung; aktuelles Gesetz geht vor. Die EU-Richtlinie ist in der durchsuchbaren konsolidierten Fassung vom 14.04.2025 verlinkt. Ausländische Steuersätze, lokales Reverse Charge und Registrierung vor Ort bestätigen.</p><p>Die Auswahl wird im Browser verarbeitet. Keine echten Kundennamen, Beträge oder Nummern nötig; keine Beleguploads oder externen Analyseskripte. Die Sprachpräferenz bleibt in diesem Browser. Beim Sprachwechsel werden nur die ausgewählten Fakten vorübergehend innerhalb der Sitzung übertragen, um den Fortschritt zu erhalten. Die öffentliche Version hat keine Zugriffskontrolle. Keine vertraulichen Angaben eingeben.</p></article></div><div class="section-actions"><button class="btn primary" data-view="case">Zurück zur Transaktionsprüfung →</button></div>`;
}
function renderValidation(){const results=testCases.map(t=>({...t,pass:runCase(t)})),pass=results.filter(x=>x.pass).length;
 $('#validation-view').innerHTML=`<div class="section-heading"><div class="eyebrow">FALLPRÜFUNG · V2</div><h1>Hauptfälle und Gegenbeispiele einzeln geprüft.</h1><p>Beim Öffnen werden die aktuellen Regeln erneut ausgeführt. Tests prüfen Ergebnisse und wesentliche Schutzbedingungen.</p></div><div class="validation-banner"><div><strong>${pass} / ${results.length} Fälle bestanden</strong><p>Regelversion ${VERSION} · live auf dieser Seite ausgeführt</p></div><span>${pass===results.length?"✓ Alle Prüfungen bestanden":"! Fehler vorhanden"}</span></div><div class="validation-table"><table class="rule-table"><thead><tr><th>Fall</th><th>Erwartetes Verhalten</th><th>Ergebnis</th></tr></thead><tbody>${results.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.expect)}</td><td><span class="pass ${t.pass?'':'failed'}">${t.pass?"Bestanden":"Fehlgeschlagen"}</span></td></tr>`).join('')}</tbody></table></div><p class="table-foot">Tests prüfen die Übereinstimmung mit vorgegebenen Regeln. Sie ersetzen keine Bestätigung tatsächlicher Verträge, Nummern, Belege, Behörden oder ausländischer Berater. Unbekannte Schlüsselfakten werden nicht automatisch zu bestätigter Befreiung oder Vereinfachungsregelung für Dreiecksgeschäfte.</p><div class="section-actions"><button class="btn primary" data-view="case">Transaktion prüfen →</button></div>`;
}
function setPreset(id){const p=PRESETS.find(x=>x.id===id);state={...p.state};activePreset=id;step=0;render();}
function reset(){state={...base,supplierCountry:'UNKNOWN',recipient:'UNKNOWN',transaction:'UNKNOWN',scope:'UNKNOWN',origin:'UNKNOWN',direct:'UNKNOWN',disposal:'UNKNOWN',transport:'UNKNOWN',purchaseVat:'UNKNOWN',purchaseValid:'UNKNOWN',salesVat:'UNKNOWN',customerValid:'UNKNOWN',timing:'UNKNOWN'};step=0;activePreset=null;render();toast("Wesentliche Angaben zurückgesetzt");}
function navigateStep(i){step=i;renderQuestions();$('.question-panel').scrollIntoView({behavior:'auto',block:'start'});}
 document.addEventListener('click',e=>{const el=e.target.closest('button,a.brand');if(!el)return;if(el.dataset.language){switchLanguage(el.dataset.language,{state,step,resultTab,activePreset,currentView});return;}if(el.matches('a.brand')){e.preventDefault();showView('case');return;}if(el.dataset.view){showView(el.dataset.view);return;}if(el.dataset.key){setField(el.dataset.key,el.dataset.value);return;}if(el.dataset.preset){setPreset(el.dataset.preset);return;}if(el.dataset.step!==undefined){navigateStep(Number(el.dataset.step));return;}if(el.dataset.result){resultTab=el.dataset.result;renderResult();return;}if(el.id==='next'){if(step<4)navigateStep(step+1);else{resultTab='invoice';renderResult();$('.result-tabs').scrollIntoView({behavior:'auto',block:'start'});}return;}if(el.id==='back'){navigateStep(Math.max(0,step-1));return;}if(el.id==='reset')reset();if(el.id==='copy-report')copy(report());if(el.id==='show-record')showRecord();if(el.id==='copy-wording')copy(evaluate(state).wording);if(el.id==='download-record')downloadRecord();if(el.id==='close-record')$('#record-dialog').close();if(el.id==='copy-record-text')copy($('#record-text').value);if(el.id==='print-report'){$('#print-area').textContent=report();window.print();}});
 document.addEventListener('change',e=>{if(e.target.matches('select[data-key]'))setField(e.target.dataset.key,e.target.value);});
renderRules();render();if(currentView!=='case')showView(currentView);
